package com.primehr.succession.domain;
import com.primehr.rsp.domain.RspAuditedEntity; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="succession_committee_conflict")
public class SuccessionCommitteeConflict extends RspAuditedEntity {
 public enum Type{PERSONAL,PROFESSIONAL,SUPERVISORY,OTHER} public enum Status{ACTIVE,RESOLVED}
 @Column(name="charter_version_id",nullable=false,length=36) private String charterVersionId; @Column(name="declaring_employee_no",nullable=false,length=100) private String declaringEmployeeNo; @Column(name="related_employee_no",nullable=false,length=100) private String relatedEmployeeNo; @Enumerated(EnumType.STRING) @Column(name="conflict_type",nullable=false,length=30) private Type conflictType; @Column(nullable=false,length=2000) private String details; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private Status status; @Column(name="declared_by",nullable=false,length=100) private String declaredBy; @Column(name="declared_at",nullable=false) private Instant declaredAt; @Column(name="resolved_by",length=100) private String resolvedBy; @Column(name="resolved_at") private Instant resolvedAt; @Column(name="resolution_reason",length=1000) private String resolutionReason;
 protected SuccessionCommitteeConflict(){}
 public SuccessionCommitteeConflict(String agencyId,String charterVersionId,String declaring,String related,Type type,String details,String actor,Instant at){super(agencyId);this.charterVersionId=requiredText(charterVersionId,"charterVersionId");declaringEmployeeNo=requiredText(declaring,"declaringEmployeeNo");relatedEmployeeNo=requiredText(related,"relatedEmployeeNo");if(declaringEmployeeNo.equalsIgnoreCase(relatedEmployeeNo))throw new IllegalArgumentException("A conflict must identify another employee");if(type==null)throw new IllegalArgumentException("conflictType is required");conflictType=type;this.details=requiredText(details,"details");declaredBy=requiredText(actor,"actor");declaredAt=at;status=Status.ACTIVE;}
 public void resolve(String actor,String reason,Instant at){if(status!=Status.ACTIVE)throw new IllegalArgumentException("Conflict is already resolved");resolvedBy=requiredText(actor,"actor");resolutionReason=requiredText(reason,"reason");resolvedAt=at;status=Status.RESOLVED;}
 public String getCharterVersionId(){return charterVersionId;} public String getDeclaringEmployeeNo(){return declaringEmployeeNo;} public String getRelatedEmployeeNo(){return relatedEmployeeNo;} public Type getConflictType(){return conflictType;} public String getDetails(){return details;} public Status getStatus(){return status;} public String getDeclaredBy(){return declaredBy;} public Instant getDeclaredAt(){return declaredAt;} public String getResolvedBy(){return resolvedBy;} public Instant getResolvedAt(){return resolvedAt;} public String getResolutionReason(){return resolutionReason;}
}
